begin;
select plan(23);
insert into auth.users(id,email) values('00000000-0000-0000-0000-000000000123','jasonblick@zohomail.com');
insert into pair_trades(id,user_id,config) values('00000000-0000-0000-0000-000000000124','00000000-0000-0000-0000-000000000123','{"name":"Test","source":"manual","assetA":"BTC","assetB":"ETH","legs":[{},{}],"alerts":{"profit":"1"}}');
select is(observe_pair_alert('00000000-0000-0000-0000-000000000124','profit',true,'Test'),true,'first crossing queues one notice');
select is(observe_pair_alert('00000000-0000-0000-0000-000000000124','profit',true,'Test'),false,'continued breach cannot spam');
select is((select count(*)::integer from pair_alert_outbox),1,'one durable notice');
select observe_pair_alert('00000000-0000-0000-0000-000000000124','profit',false,'Test');
select observe_pair_alert('00000000-0000-0000-0000-000000000124','profit',false,'Test');
select is((select breached from pair_alert_state),true,'two observations cannot rearm');
select observe_pair_alert('00000000-0000-0000-0000-000000000124','profit',false,'Test');
select is((select breached from pair_alert_state),false,'three clear observations rearm');
select is(observe_pair_alert('00000000-0000-0000-0000-000000000124','profit',true,'Test'),false,'cooldown still suppresses notice');
select * from claim_pair_alerts();
select is((select attempts from pair_alert_outbox),1,'claim records attempt');
select is((select count(*)::integer from claim_pair_alerts()),0,'leased notification cannot be claimed twice');
select is(finish_pair_alert((select id from pair_alert_outbox),'00000000-0000-0000-0000-000000000000',null),false,'wrong lease cannot finish');
select is(finish_pair_alert((select id from pair_alert_outbox),(select lease_token from pair_alert_outbox),'test failure'),true,'retry is fenced');
select is((select state from pair_alert_outbox),'queued','failed delivery retries');
update pair_alert_outbox set attempts=5,next_attempt_at=now();
select * from claim_pair_alerts();
select finish_pair_alert((select id from pair_alert_outbox),(select lease_token from pair_alert_outbox),'test failure');
select is((select state from pair_alert_outbox),'failed','six failures stop repeated delivery');
select function_privs_are('public','observe_pair_alert',array['uuid','text','boolean','text'],'authenticated',array[]::text[],'browser cannot queue notifications');
select function_privs_are('public','claim_pair_alerts',array[]::text[],'authenticated',array[]::text[],'browser cannot claim notifications');
select function_privs_are('public','claim_comparison_history',array[]::text[],'authenticated',array[]::text[],'browser cannot act as history worker');
select is(has_table_privilege('authenticated','pair_live_accounts','INSERT'),false,'browser cannot invent linked positions');
select is(has_table_privilege('authenticated','pair_mark_quotes','UPDATE'),false,'browser cannot rewrite marks');
select is(has_table_privilege('authenticated','comparison_history_cache','UPDATE'),false,'browser cannot fabricate historical prices');
select throws_ok($$select request_comparison_history('BTC','1m',1,2)$$,'P0001','Owner only','history rejects missing owner identity');
select throws_ok($$select pair_mark_history(array['BTC','ETH'],now()-interval '1 hour',now())$$,'P0001','Owner only','mark history rejects missing owner identity');
insert into pair_alert_outbox(pair_id,user_id,metric,message) select '00000000-0000-0000-0000-000000000124','00000000-0000-0000-0000-000000000123','profit','test' from generate_series(1,3);
update pair_alert_state set breached=false,last_notice=now()-interval '1 hour';
select is(observe_pair_alert('00000000-0000-0000-0000-000000000124','profit',true,'Test'),false,'four notices in 24 hours is a hard cap even after recovery and cooldown');
update pair_alert_outbox set state='claimed',attempts=6,lease_until=now()-interval '1 minute';
select is((select count(*)::integer from claim_pair_alerts()),0,'six expired leases cannot cause unlimited crash recovery sends');
update pair_alert_outbox set state='queued',attempts=0,next_attempt_at=now();
update pair_trades set archived=true;
select is((select count(*)::integer from claim_pair_alerts()),0,'archiving a pair cancels queued notifications');
select * from finish();
rollback;
